'use strict';
// Words: every player-facing string is a key in rumble-demo-data.js (DEMO.page, read as PAGE and COPY), rumble-cues-data.js or
// drag-feedback-data.js. The markup carries none; WORDS gives each element its words at boot. rumble-copy.test.cjs fails on a new inline string.
const DEMO=window.LoftRumbleDemoData.copy,PAGE=DEMO.page;
const phrase=(template,values)=>template.replace(/\{(\w+)\}/g,(_,key)=>String(values[key]??''));
const WORDS=[['h1','aria-label',PAGE.gameName],['#pause','aria-label',PAGE.pause],['#menu-toggle','aria-label',PAGE.settings],
  ['#help-toggle','aria-label',DEMO.helpMenu],['#health','aria-label',PAGE.bossBar],['#reset','text',PAGE.newBattle],
  ['#reroll','text',PAGE.reroll],['#replay-tutorial','text',PAGE.replayTutorial],['.mode-link','text',PAGE.turnBased],
  ['#portrait-hint span','text',PAGE.portraitHint],['#hint-close','text',PAGE.dismiss]];
// A node can be absent: the published build strips the turn-based link (game/build/rumble-release.mjs), so skip what is not there.
for(const [selector,attribute,words] of WORDS){const node=document.querySelector(selector);if(!node)continue;if(attribute==='text')node.textContent=words;else node.setAttribute(attribute,words)}
// All distances/speeds are logical arena units (per second). The arena is a fixed C.arenaW x C.arenaH portrait playfield,
// scaled to fit its container, so ranges and bounce counts are identical on every screen. Prototype feel-test values.
// hp 600 (round 8): with the bounce multiplier, an average-player sim (40 battles per trait) wins in a median 12-13 shots.
const C={arenaW:360,arenaH:640,hudTop:50,hudBottom:32,radius:15,visualSize:46,ringLife:.32,popupLife:.95,enemyRadius:38,hp:600,weakArc:.55,weakMultiplier:3,maxBonusWalls:3,stopSpeed:45,hitCooldown:.22,step:1/180,maxFrame:.04,padding:7,hitReach:47,particleLife:.65,particleCount:12,aimStep:.12,enemyX:.5,enemyY:.3,homeX:.22,homeY:.82,
  weakAngle:Math.PI/2}; // owner 2026-11-18: the weak spot faces the player (was 2.55, lower-left) so its shield shows the carved front art
// Feel tuning, polish pass 2026-11-08. Seconds, CSS px, px/s. Colours are the CSS tokens in :root, named here by key.
