 cancelRadius:30,                      // minimum pull: shorter drags cancel, so a stray touch never fires; past it the shot is armed
 aimSegments:24,                       // trace() walks the whole budget, up to this many wall or enemy bounces
 // Aim guide (round 5, owner: the round-0 straight dotted line "felt more natural"): aimDots dots every aimGap units
