 bulletTime:false,                     // round 11: slow-mo while aiming (RT.slowFactor, Focus) is off; owner: "too good, and it wouldn't make sense in PvP". Kept for a charm or special.
 // Timing gauge (round 5, Monster Strike's gauge shot; back in round 11): sweeps 0->1->0 each gaugeCycle seconds while a pulled aim is held.
 // Release within greatHalf of gaugeCenter = Great, within perfectHalf = Perfect. Elsewhere is a normal shot, no penalty.
 // Round 15 (owner: the gauge made every shot anxious): it fades in only after gaugeDelay of holding a pulled aim; a quicker release is a normal shot.
 gaugeDelay:.3,gaugeFade:.15,          // seconds of held pull before the sweep starts, and its fade-in
 gaugeCycle:1.3,gaugeCenter:.85,greatHalf:.12,perfectHalf:.05, // round 15: cycle slowed from 1.1 s; windows unchanged
